static int find_set(int *parent, int x) {
    if (parent[x] != x) parent[x] = find_set(parent, parent[x]);
    return parent[x];
}

static void union_set(int *parent, int *rankv, int a, int b) {
    a = find_set(parent, a);
    b = find_set(parent, b);
    if (a == b) return;
    if (rankv[a] < rankv[b]) {
        parent[a] = b;
    } else if (rankv[a] > rankv[b]) {
        parent[b] = a;
    } else {
        parent[b] = a;
        rankv[a]++;
    }
}

int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    int *parent = (int *)malloc((N + 1) * sizeof(int));
    int *rankv  = (int *)calloc(N + 1, sizeof(int));
    for (int i = 1; i <= N; i++) parent[i] = i;

    for (int i = 0; i < M; i++) {
        int a, b, c;
        scanf("%d %d %d", &a, &b, &c);
        /* Since card values are 1 or 2, parity determines the value uniquely:
           1 is odd, 2 is even.
           Condition: ai + aj + c is even
           => parity(ai) XOR parity(aj) = parity(c)
           Thus each condition gives whether ai and aj have same/different parity.
           To determine all values, in each connected component of this relation graph,
           revealing one card determines the rest. So answer = number of connected components.
           For connectivity only, every condition connects a and b.
        */
        union_set(parent, rankv, a, b);
    }

    int ans = 0;
    for (int i = 1; i <= N; i++) {
        if (find_set(parent, i) == i) ans++;
    }

    printf("%d\n", ans);

    free(parent);
    free(rankv);
    return 0;
}

