public class Main {
    static int[] parent, rank;
    static int[] parity; // parity relative to parent

    static int find(int x) {
        if (parent[x] == x) return x;
        int root = find(parent[x]);
        parity[x] ^= parity[parent[x]];
        parent[x] = root;
        return root;
    }

    static boolean union(int x, int y, int rel) {
        // rel = 0 means same, rel = 1 means different
        int rx = find(x), ry = find(y);
        int px = parity[x], py = parity[y];
        if (rx == ry) {
            // check consistency; if inconsistent, component is over-constrained
            return (px ^ py) == rel;
        }
        if (rank[rx] < rank[ry]) { int t = rx; rx = ry; ry = t; t = px; px = py; py = t; int tmp = x; x = y; y = tmp; }
        parent[ry] = rx;
        parity[ry] = px ^ py ^ rel;
        if (rank[rx] == rank[ry]) rank[rx]++;
        return true;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt(), M = sc.nextInt();
        parent = new int[N+1]; rank = new int[N+1]; parity = new int[N+1];
        for (int i = 1; i <= N; i++) parent[i] = i;

        boolean[] nonBipartite = new boolean[N+1];

        for (int i = 0; i < M; i++) {
            int a = sc.nextInt(), b = sc.nextInt(), k = sc.nextInt();
            int rel = k % 2; // 0=same, 1=different
            boolean consistent = union(a, b, rel);
            if (!consistent) {
                nonBipartite[find(a)] = true;
            }
        }

        Set<Integer> roots = new HashSet<>();
        for (int i = 1; i <= N; i++) roots.add(find(i));

        int ans = 0;
        for (int r : roots) {
            if (!nonBipartite[r]) ans++;
        }
        System.out.println(ans);
    }
}

